def transform(grid):
    n = len(grid)
    transpose = [[grid[j][i] for j in range(n)] for i in range(n)]
    reverse_rows = [row[::-1] for row in grid[::-1]]
    reflected_transpose = [row[::-1] for row in transpose]

    return [
        grid[i] + reflected_transpose[i]
        for i in range(n)
    ] + [
        transpose[i] + reverse_rows[i]
        for i in range(n)
    ]
